render<-d1_render_packets(pair_cp,pair_run,cfg);h<-paste(render$html,collapse="\n");plain<-paste(render$plain,collapse="\n")
test("Five analytical HTML sections, no extra charts",stopifnot(count_pattern('class="analytics-slot"',h)==5L,length(render$images)==0L,!grepl("<img",h,fixed=TRUE)))
