# Integration tests use actual pipeline functions but no network or model calls.
input<-file.path(tmp,"local_fixture.json");json_write(input,list(obs1,second))
endcfg<-cfg;endcfg$analytics$history_dir<-paste0(tmp_rel,"/e2e_history");endcfg$analytics$method_cache_dir<-paste0(tmp_rel,"/e2e_cache")
e2e<-new_run("e2e_failed_audit_charts");dir.create(file.path(e2e,"logs"));dir.create(file.path(e2e,"figures"))
prepare_run(root,e2e,endcfg,"local","2026-09-20",input)
prepare_analytics(root,e2e,endcfg);run_audit_figures(root,e2e,runner=function(...)1L)
build_email(root,e2e,endcfg);qa<-validate_output(root,e2e,endcfg)
test("Failed audit-only charts do not block five-output email",stopifnot(qa$passed,qa$inline_images==1L,qa$methods_accounted==42L,grepl("not available",qa$frequency_reconciliation,fixed=TRUE)))
test("Country summaries survive withheld analytical outputs",stopifnot(qa$country_sections==1L,qa$ungrouped_statements_preserved==2L))
