empty_input<-file.path(tmp,"empty.json");json_write(empty_input,list());empty<-new_run("e2e_empty");dir.create(file.path(empty,"logs"));dir.create(file.path(empty,"figures"))
prepare_run(root,empty,endcfg,"local","2026-09-20",empty_input);prepare_analytics(root,empty,endcfg);run_audit_figures(root,empty,runner=function(...)1L);build_email(root,empty,endcfg);qe<-validate_output(root,empty,endcfg)
