summary<-list(passed=all(vapply(results,function(r)r$passed,logical(1))),tests=length(results),failed=sum(!vapply(results,function(r)r$passed,logical(1))),R_version=R.version.string,minimal=isTRUE(getOption("unbrief.minimal")),fixture_scope="Synthetic engineering data; no live requests, model training, native Outlook or Windows validation.",results=results)
json_write("validation/d1_tests.json",summary);write_text("validation/d1_tests_sessionInfo.txt",capture.output(sessionInfo()))
